    {
      "service": "ts-travel2-service",
      "fault_kind": "http_aborted",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='ts-travel2-service' AND attr_span_kind='Client' AND attr_status_code='Error' GROUP BY 1,2,3,4", "claim": "About 1004 of travel2's outbound POST client spans ended in Error with no HTTP status; normal period has none."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_http_response_status_code code, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name LIKE '%trip_detail%' GROUP BY 1,2,3", "claim": "All travel2 trip_detail server spans in the incident returned HTTP 500, versus 200 in normal."},
        {"kind": "log", "sql": "SELECT level, attr_log_template, count(*) n FROM abnormal_logs WHERE service_name='ts-travel2-service' AND level='SEVERE' GROUP BY 1,2 ORDER BY n DESC LIMIT 3", "claim": "Travel2 logs about 2400 SEVERE 'I/O error on request' ResourceAccessException exceptions during the incident."},
        {"kind": "metric", "sql": "SELECT 'abn' p, sum(value) total FROM abnormal_metrics_sum WHERE metric='hubble_http_requests_total' AND attr_source LIKE '%travel2%' AND attr_destination LIKE '%basic%' UNION ALL SELECT 'nor', sum(value) FROM normal_metrics_sum WHERE metric='hubble_http_requests_total' AND attr_source LIKE '%travel2%' AND attr_destination LIKE '%basic%'", "claim": "Travel2 to basic HTTP request count rose from about 6.3k to 23.3k while basic's server spans stayed 200."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name caller, p.service_name callee, count(*) n, sum(CASE WHEN c.attr_http_response_status_code>=500 THEN 1 ELSE 0 END) c5xx FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id WHERE c.service_name='ts-route-plan-service' AND p.service_name='ts-travel2-service' GROUP BY 1,2", "claim": "Route-plan's calls to travel2 trip_detail returned 5xx on 876 of the matched calls, averaging about 6.6s."}
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name caller, p.service_name callee, count(*) n, round(avg(c.duration)/1e6,1) caller_ms, sum(CASE WHEN c.attr_http_response_status_code>=500 THEN 1 ELSE 0 END) c5xx FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id WHERE c.service_name='ts-travel-plan-service' AND p.service_name='ts-route-plan-service' GROUP BY 1,2", "claim": "Travel-plan's calls to route-plan minStopStations averaged about 56s with 127 returning 5xx."}
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(avg(duration)/1e6,1) avg_ms, round(max(duration)/1e6,1) max_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%minStation%' GROUP BY 1,2", "claim": "UI dashboard's minStation requests averaged about 15s, with max about 20s, versus about 1.2s normal for travel-plan calls."}
      ]
    }
  ]
}
